mapper.select:
SELECT o.order_no, o.item_id, o.student_id, o.amount, o.paid_amount, o.channel, o.status, o.transaction_no, o.expire_at, o.paid_at, o.closed_at, o.created_at, i.item_no, i.item_name, i.category, s.student_no, s.college, u.real_name AS student_name FROM payment_order o INNER JOIN payment_item i ON i.id = o.item_id INNER JOIN student s ON s.id = o.student_id INNER JOIN sys_user u ON u.id = s.user_id WHERE o.deleted = 0
AND o.student_id = #{studentId}
AND o.status = #{status}
AND o.item_id = #{itemId}
AND o.channel = #{channel}
AND s.student_no LIKE CONCAT('%', #{studentNo}, '%')
AND (o.order_no LIKE CONCAT('%', #{keyword}, '%') OR o.transaction_no LIKE CONCAT('%', #{keyword}, '%') OR s.student_no LIKE CONCAT('%', #{keyword}, '%') OR u.real_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY o.created_at DESC, o.id DESC

SELECT i.item_no, i.item_name, i.category, i.amount, COALESCE(SUM(CASE WHEN o.status <> 'CLOSED' THEN o.amount ELSE 0 END), 0) AS receivable, COALESCE(SUM(CASE WHEN o.status IN ('PAID', 'PARTIAL_REFUND') THEN o.paid_amount ELSE 0 END), 0) AS received, COUNT(o.id) AS order_count, COALESCE(SUM(CASE WHEN o.status IN ('PAID', 'PARTIAL_REFUND') THEN 1 ELSE 0 END), 0) AS paid_count FROM payment_item i LEFT JOIN payment_order o ON o.item_id = i.id AND o.deleted = 0 WHERE i.deleted = 0
AND i.term = #{term}
GROUP BY i.id, i.item_no, i.item_name, i.category, i.amount ORDER BY receivable DESC, i.id DESC
